#!/usr/bin/env python3
"""Capture transport: base64 chunks, Zstandard framing and bounded CSV records.

Each capture is an independent CSV stream.  Chunks may split a code point, a
compressed frame or a CSV record, so chunk bytes are concatenated before the
stream is decoded.  Transport, encoding, header and budget failures invalidate
the whole capture set (``{"error":"capture"}``); a bad *logical data record*
only rejects that record's index.
"""
import argparse
import csv
import io
import ipaddress
import json
import sys

import zstandard as zstd

from common import (COLUMNS, CaptureError, DECODED_BUDGET, Invalid, MAX_FIELD,
                    MAX_RECORDS, PLAIN_BUDGET, decode64)
from ledger import parse_record

csv.field_size_limit(MAX_FIELD)

ZSTD_MAGIC = 0xfd2fb528
SKIPPABLE_FIRST = 0x184d2a50
SKIPPABLE_LAST = 0x184d2a5f
WINDOW_LIMIT = 128 * 1024**2

# Frame header descriptor bits (RFC 8878 section 3.1.1.1).
BIT_SINGLE_SEGMENT = 0x20
BIT_UNUSED = 0x10
BIT_RESERVED = 0x08
BIT_CHECKSUM = 0x04
BLOCK_RAW = 1
BLOCK_RLE = 2
BLOCK_COMPRESSED = 3


def complete_frames(data):
    """Validate complete, dictionary-free, bounded-window Zstandard framing.

    Concatenated and skippable frames are allowed.  The walk is structural:
    checksum correctness is verified again by the decompressor.
    """
    end = len(data)
    at = 0
    while at < end:
        if at + 4 > end:
            raise CaptureError('truncated Zstandard magic')
        magic = int.from_bytes(data[at:at + 4], 'little')
        if SKIPPABLE_FIRST <= magic <= SKIPPABLE_LAST:
            if at + 8 > end:
                raise CaptureError('truncated skippable frame')
            size = int.from_bytes(data[at + 4:at + 8], 'little')
            at += 8 + size
            if at > end:
                raise CaptureError('truncated skippable frame')
            continue
        if magic != ZSTD_MAGIC:
            raise CaptureError('invalid Zstandard magic')
        if at + 5 > end:
            raise CaptureError('truncated Zstandard frame header')
        flag = data[at + 4]
        if flag & BIT_RESERVED:
            raise CaptureError('reserved Zstandard frame bit')
        single = bool(flag & BIT_SINGLE_SEGMENT)
        dictionary = (0, 1, 2, 4)[flag & 3]
        content = (1 if single else 0, 2, 4, 8)[flag >> 6]
        header = 5 + (0 if single else 1) + dictionary + content
        if at + header > end:
            raise CaptureError('truncated Zstandard frame header')
        if dictionary:
            raise CaptureError('dictionary Zstandard frame')
        parameters = zstd.get_frame_parameters(data[at:at + header])
        if parameters.dict_id:
            raise CaptureError('dictionary Zstandard frame')
        if parameters.window_size > WINDOW_LIMIT:
            raise CaptureError('Zstandard window too large')
        at += header
        while True:
            if at + 3 > end:
                raise CaptureError('truncated Zstandard block header')
            block = int.from_bytes(data[at:at + 3], 'little')
            at += 3
            kind = (block >> 1) & 3
            size = block >> 3
            if kind == 0 or kind > 3:
                raise CaptureError('reserved Zstandard block type')
            at += 1 if kind == BLOCK_RLE else size
            if at > end:
                raise CaptureError('truncated Zstandard block')
            if block & 1:
                break
        if flag & BIT_CHECKSUM:
            at += 4
        if at > end:
            raise CaptureError('truncated Zstandard checksum')


class BoundedReader(io.RawIOBase):
    """Byte-budget view over a decompressed stream (plain CSV also counts)."""

    def __init__(self, source, budget):
        self.source = source
        self.budget = budget

    def readable(self):
        return True

    def readinto(self, buffer):
        left = self.budget[0] - len(buffer)
        if left < 0:
            raise CaptureError('decompressed byte budget')
        view = memoryview(buffer)[:left] if left else memoryview(buffer)[:0]
        block = self.source.read(len(view))
        if not block:
            self.budget[0] -= 0
            return 0
        self.budget[0] -= len(block)
        if self.budget[0] < 0:
            raise CaptureError('decompressed byte budget')
        buffer[:len(block)] = block
        return len(block)

    def close(self):
        try:
            self.source.close()
        except AttributeError:
            pass
        super().close()


def byte_stream(chunks, encoding):
    """Decode base64 chunks and return a raw (possibly compressed) byte stream."""
    blocks = [decode64(text, CaptureError) for text in chunks]
    blob = b''.join(blocks)
    if encoding == 'zstd':
        try:
            complete_frames(blob)
        except zstd.ZstdError as exc:
            raise CaptureError('invalid Zstandard frame') from exc
        reader = zstd.ZstdDecompressor(
            max_window_size=WINDOW_LIMIT).stream_reader(io.BytesIO(blob),
                                                        read_across_frames=True)
        return reader, len(blob)
    del blocks
    return io.BytesIO(blob), len(blob)


def logical_rows(stream, budget):
    """Yield logical CSV records of one UTF-8 stream."""
    bounded = io.BufferedReader(BoundedReader(stream, budget))
    text = io.TextIOWrapper(bounded, encoding='utf-8', newline='')
    return csv.reader(text, strict=True), text


def capture_records(context, probes):
    """Return (valid parsed records, rejected [capture, ordinal] pairs)."""
    records = []
    rejected = []
    budget = [PLAIN_BUDGET]
    decoded = 0
    rows_count = 0
    want_header = list(COLUMNS)
    for number, capture in enumerate(context['captures']):
        stream, size = byte_stream(capture['chunks'], capture['encoding'])
        decoded += size
        if decoded > DECODED_BUDGET:
            raise CaptureError('decoded byte budget')
        try:
            reader, text = logical_rows(stream, budget)
            try:
                if next(reader, None) != want_header:
                    raise CaptureError('invalid CSV header')
                ordinal = 0
                for values in reader:
                    count = ordinal
                    ordinal += 1
                    rows_count += 1
                    if rows_count > MAX_RECORDS:
                        raise CaptureError('record count budget')
                    for value in values:
                        if len(value) > MAX_FIELD:
                            raise CaptureError('field byte budget')
                        if not value.isascii() and \
                                len(value.encode('utf-8')) > MAX_FIELD:
                            raise CaptureError('field byte budget')
                    try:
                        records.append(parse_record(values, context, probes))
                    except (Invalid, ValueError, TypeError, UnicodeError):
                        rejected.append([number, count])
            finally:
                text.close()
        except UnicodeError as exc:
            raise CaptureError('invalid UTF-8 capture') from exc
        except csv.Error as exc:
            raise CaptureError('invalid CSV syntax') from exc
        except zstd.ZstdError as exc:
            raise CaptureError('invalid Zstandard stream') from exc
        except EOFError as exc:
            raise CaptureError('truncated capture') from exc
        except RecursionError:
            raise CaptureError('capture stream failure')
    return records, rejected


# ---- legacy development helpers (not part of the campaign interface) --------

def stream_csv(path, encoding='zstd', budget=None):
    handle = open(path, 'rb')
    source = (zstd.ZstdDecompressor().stream_reader(handle, read_across_frames=True)
              if encoding == 'zstd' else handle)
    bounded = io.BufferedReader(BoundedReader(source, budget)) if budget else source
    with io.TextIOWrapper(bounded, encoding='utf-8', newline='') as text:
        yield from csv.reader(text, strict=True)


def record_response(networks, key, target, responder, same_is_internal=True):
    bucket = networks.setdefault(key, {'network': key, 'internal': set(),
                                       'external': set()})
    if target == responder:
        if not same_is_internal:
            return None
        role = 'internal'
    else:
        role = 'external'
    bucket[role].add(responder)
    return role


def main():
    parser = argparse.ArgumentParser(
        description='Group legacy ZMap6 responses by /64 network')
    parser.add_argument('aliases_file')
    parser.add_argument('zmap_csv')
    parser.add_argument('--encoding', default='zstd', choices=('csv', 'zstd'))
    args = parser.parse_args()
    aliases = {line.strip() for line in open(args.aliases_file)}
    networks = {}
    for values in stream_csv(args.zmap_csv, args.encoding):
        if not values or values[0] == 'saddr' or len(values) < 2:
            continue
        target, responder = values[0], values[1]
        try:
            net64 = ':'.join(ipaddress.IPv6Address(target).exploded.split(':')[:4])
        except ValueError:
            continue
        if net64 in aliases:
            continue
        record_response(networks, net64, target, responder)
    for entry in networks.values():
        entry['internal'] = sorted(entry['internal'])
        entry['external'] = sorted(entry['external'])
        print(json.dumps(entry))


if __name__ == '__main__':
    sys.exit(main())
